\pset pager off
SELECT version();
SELECT 'conteos' AS seccion, (SELECT count(*) FROM productos) productos, (SELECT count(*) FROM stock_actual) stocks, (SELECT count(*) FROM inventario_movimientos) movimientos, (SELECT count(*) FROM alertas_stock) alertas;
SELECT tablename,indexname,indexdef FROM pg_indexes WHERE tablename IN ('productos','stock_actual','inventario_movimientos','alertas_stock','precios_actuales') ORDER BY tablename,indexname;
SELECT conrelid::regclass AS tabla,conname,pg_get_constraintdef(oid) AS definicion FROM pg_constraint WHERE conrelid IN ('productos'::regclass,'stock_actual'::regclass,'inventario_movimientos'::regclass,'alertas_stock'::regclass,'precios_actuales'::regclass) ORDER BY 1,2;
SELECT 'agregados' AS seccion,count(*) AS inconsistencias FROM productos p WHERE stock_total <> COALESCE((SELECT sum(cantidad) FROM stock_actual s WHERE s.id_producto=p.id_producto),0) OR stock_principal <> COALESCE((SELECT sum(s.cantidad) FROM stock_actual s JOIN almacenes a USING(id_almacen) WHERE s.id_producto=p.id_producto AND a.codigo='ALM-001'),0);
SELECT 'kardex_balance' AS seccion,count(*) AS inconsistencias FROM stock_actual s WHERE cantidad <> COALESCE((SELECT sum(m.stock_posterior-m.stock_anterior) FROM inventario_movimientos m WHERE m.id_producto=s.id_producto AND m.id_almacen=s.id_almacen),0);
WITH cadena AS (SELECT *,lag(stock_posterior) OVER (PARTITION BY id_producto,id_almacen ORDER BY id_movimiento) previo FROM inventario_movimientos) SELECT 'cadena_kardex' seccion,count(*) inconsistencias FROM cadena WHERE (previo IS NOT NULL AND previo<>stock_anterior) OR (tipo='entrada' AND stock_posterior-stock_anterior<>cantidad) OR (tipo='salida' AND stock_anterior-stock_posterior<>cantidad);
SELECT 'negativos' seccion,(SELECT count(*) FROM stock_actual WHERE cantidad<0) stocks,(SELECT count(*) FROM productos WHERE stock_total<0 OR stock_principal<0 OR stock_minimo<0) productos,(SELECT count(*) FROM precios_actuales WHERE LEAST(costo_normal,precio_unidad_normal,precio_docena_normal,precio_mayor_normal,costo_distribuidor,precio_unidad_dist,precio_docena_dist,precio_mayor_dist)<0) precios;
SELECT 'alertas_faltantes' seccion,count(*) FROM stock_actual s JOIN productos p USING(id_producto) WHERE p.deleted_at IS NULL AND s.cantidad<=p.stock_minimo AND NOT EXISTS(SELECT 1 FROM alertas_stock a WHERE a.id_producto=s.id_producto AND a.id_almacen=s.id_almacen AND a.estado='activa');
SELECT 'alertas_desactualizadas' seccion,count(*) FROM alertas_stock a JOIN stock_actual s USING(id_producto,id_almacen) JOIN productos p USING(id_producto) WHERE a.estado='activa' AND (a.stock_actual<>s.cantidad OR a.stock_minimo<>p.stock_minimo OR s.cantidad>p.stock_minimo);
SELECT 'alertas_duplicadas' seccion,count(*) FROM (SELECT id_producto,id_almacen FROM alertas_stock GROUP BY 1,2 HAVING count(*)>1) a;
SELECT migration_name, finished_at IS NOT NULL AS aplicada FROM _prisma_migrations ORDER BY migration_name;
